import{_ as t,o as s,c as o,l as r,t as n,N as a}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"ipcrm | x-cmd man (ip man1) | remove certain IPC resources","titleTemplate":false,"description":"x-cmd man (ip man1 Manual Page) | ipcrm - remove certain IPC resources","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ipcrm | x-cmd man (ip man1) | remove certain IPC resources"}],["meta",{"name":"og:description","content":"x-cmd man (ip man1 Manual Page) | ipcrm - remove certain IPC resources"}]]},"headers":[],"params":{"isMan":true,"man":"ipcrm","category":"ip man1","desc":"remove certain IPC resources"},"relativePath":"ip/man1/ipcrm.md","filePath":"ip/man1/ipcrm.md"}'),i={name:"ip/man1/ipcrm.md"},m={class:"visually-hidden"},c=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ipcrm - remove certain IPC resources</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ipcrm</strong> [options]</p><p><strong>ipcrm</strong> [<strong>shm</strong>|<strong>msg</strong>|<strong>sem</strong>] <em>ID</em> ...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>ipcrm</strong> removes System V inter-process communication (IPC) objects and associated data structures from the system. In order to delete such objects, you must be superuser, or the creator or owner of the object.</p><p>System V IPC objects are of three types: shared memory, message queues, and semaphores. Deletion of a message queue or semaphore object is immediate (regardless of whether any process still holds an IPC identifier for the object). A shared memory object is only removed after all currently attached processes have detached (<strong>shmdt</strong>(2)) the object from their virtual address space.</p><p>Two syntax styles are supported. The old Linux historical syntax specifies a three-letter keyword indicating which class of object is to be deleted, followed by one or more IPC identifiers for objects of this type.</p><p>The SUS-compliant syntax allows the specification of zero or more objects of all three types in a single command line, with objects specified either by key or by identifier (see below). Both keys and identifiers may be specified in decimal, hexadecimal (specified with an initial &#39;0x&#39; or &#39;0X&#39;), or octal (specified with an initial &#39;0&#39;).</p><p>The details of the removes are described in <strong>shmctl</strong>(2), <strong>msgctl</strong>(2), and <strong>semctl</strong>(2). The identifiers and keys can be found by using <strong>ipcs</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-a</strong>, <strong>--all</strong> [<strong>shm</strong>] [<strong>msg</strong>] [<strong>sem</strong>]</p><blockquote><p>Remove all resources. When an option argument is provided, the removal is performed only for the specified resource types.</p><p><em>Warning!</em> Do not use <strong>-a</strong> if you are unsure how the software using the resources might react to missing objects. Some programs create these resources at startup and may not have any code to deal with an unexpected disappearance.</p></blockquote><p><strong>-M</strong>, <strong>--shmem-key</strong> <em>shmkey</em></p><blockquote><p>Remove the shared memory segment created with <em>shmkey</em> after the last detach is performed.</p></blockquote><p><strong>-m</strong>, <strong>--shmem-id</strong> <em>shmid</em></p><blockquote><p>Remove the shared memory segment identified by <em>shmid</em> after the last detach is performed.</p></blockquote><p><strong>-Q</strong>, <strong>--queue-key</strong> <em>msgkey</em></p><blockquote><p>Remove the message queue created with <em>msgkey</em>.</p></blockquote><p><strong>-q</strong>, <strong>--queue-id</strong> <em>msgid</em></p><blockquote><p>Remove the message queue identified by <em>msgid</em>.</p></blockquote><p><strong>-S</strong>, <strong>--semaphore-key</strong> <em>semkey</em></p><blockquote><p>Remove the semaphore created with <em>semkey</em>.</p></blockquote><p><strong>-s</strong>, <strong>--semaphore-id</strong> <em>semid</em></p><blockquote><p>Remove the semaphore identified by <em>semid</em>.</p></blockquote><p><strong>-h</strong>, <strong>--help</strong></p><blockquote><p>Display help text and exit.</p></blockquote><p><strong>-V</strong>, <strong>--version</strong></p><blockquote><p>Print version and exit.</p></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>In its first Linux implementation, <strong>ipcrm</strong> used the deprecated syntax shown in the second line of the <strong>SYNOPSIS</strong>. Functionality present in other *nix implementations of <strong>ipcrm</strong> has since been added, namely the ability to delete resources by key (not just identifier), and to respect the same command-line syntax. For backward compatibility the previous syntax is still supported.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>ipcmk</strong>(1), <strong>ipcs</strong>(1), <strong>msgctl</strong>(2), <strong>msgget</strong>(2), <strong>semctl</strong>(2), <strong>semget</strong>(2), <strong>shmctl</strong>(2), <strong>shmdt</strong>(2), <strong>shmget</strong>(2), <strong>ftok</strong>(3), <strong>sysvipc</strong>(7)</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>For bug reports, use the issue tracker at &lt;<a href="https://github.com/util-linux/util-linux/issues%5C" target="_blank" rel="noreferrer">https://github.com/util-linux/util-linux/issues\\</a>&gt;.</p><h2 id="availability" tabindex="-1">AVAILABILITY <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;AVAILABILITY&quot;">​</a></h2><p>The <strong>ipcrm</strong> command is part of the util-linux package which can be downloaded from <em>Linux Kernel Archive</em> &lt;<a href="https://www.kernel.org/pub/linux/utils/util-linux/%5C" target="_blank" rel="noreferrer">https://www.kernel.org/pub/linux/utils/util-linux/\\</a>&gt;.</p>',38);function p(e,l,h,d,g,u){return s(),o("div",null,[r("h1",m,n(e.$params.man),1),c])}const y=t(i,[["render",p]]);export{f as __pageData,y as default};
